#!/usr/bin/env python3
"""Сценарий голосового гида по курсу (21.11.2026): tools/guide/script.json.
Реплики двух ролей: n - проводник (Даулет / Дмитрий: куда идти, что дальше), c - тренер (Айгүль / Светлана: оценка результата, советы).
Темы и числа берутся из src/data/course/*.js, так что при правке курса сценарий пересобирается. Тексты без длинных тире.
Казахские реплики написаны Claude и ждут вычитки носителем: список выводится в tools/kk-review-guide-2026-11-21.md."""
import json, pathlib, subprocess
ROOT = pathlib.Path(__file__).resolve().parent.parent.parent
NODE = r"""
global.window = global; global.KZ = { courses: {}, tests: [] };
const fs = require('fs');
for (const l of ['a1', 'a2', 'b1', 'b2']) eval(fs.readFileSync('src/data/course/' + l + '.js', 'utf8'));
console.log(JSON.stringify(Object.values(KZ.courses).map(c => ({ level: c.level, topics: c.topics.map(t => ({ id: t.id, ru: t.ru, kk: t.kk, order: t.order, words: t.words.length })) }))));
"""
courses = json.loads(subprocess.check_output(['node', '-e', NODE], cwd=ROOT, text=True).replace(' \u2014 ', ' - '))
S = []
def add(key, role, ru, kk): S.append({'key': key, 'role': role, 'ru': ru, 'kk': kk})

# проводник
add('n.welcome', 'n', 'Привет! Я твой проводник по курсу. Мы пойдём по порядку: слова, грамматика, тексты и тест по каждой теме. Я подскажу, что делать дальше.',
    'Сәлем! Мен курс бойынша сіздің жолсерігіңізбін. Әр тақырыпты ретімен өтеміз: сөздер, грамматика, мәтіндер және тест. Келесі қадамды өзім айтып тұрамын.')
add('n.headphones', 'n', 'Совет: надень наушники. Так лучше слышно, и ничто не отвлекает. А если включить автогид, я буду сам подсказывать каждый шаг.',
    'Кеңес: құлаққап киіңіз. Сонда жақсы естіледі және ештеңе алаңдатпайды. Ал автогидті қоссаңыз, әр қадамды өзім айтып отырамын.')
for c in courses:
    f = c['topics'][0]; W = sum(t['words'] for t in c['topics'])
    add(f"n.level.{c['level']}", 'n', f"Уровень {c['level']}. В курсе {len(c['topics'])} тем и {W} слов. Идём по порядку, начнём с темы «{f['ru']}».",
        f"{c['level']} деңгейі. Курста {len(c['topics'])} тақырып және {W} сөз бар. Ретімен жүреміз, «{f['kk']}» тақырыбынан бастаймыз.")
    for t in c['topics']:
        add(f"n.topic.{c['level']}.{t['id']}", 'n', f"Тема {t['order']}: «{t['ru']}». Начни со слов, их {t['words']}. Открывай карточку, смотри перевод и отмечай, какие знаешь.",
            f"{t['order']}-тақырып: «{t['kk']}». Сөздерден бастаңыз, олар {t['words']}. Картаны ашып, аудармасын қараңыз да, білетіндеріңізді белгілеңіз.")
add('n.tab.words', 'n', 'Слова. Отмечай те, которые уже знаешь, а остальные останутся на повторение. Потом проверь себя в быстром тесте.',
    'Сөздер. Білетіндеріңізді белгілеңіз, қалғаны қайталауға қалады. Содан кейін жылдам тестпен өзіңізді тексеріңіз.')
add('n.tab.grammar', 'n', 'Грамматика. Сначала прочитай правило, потом выполни задания и проверь себя.',
    'Грамматика. Алдымен ережені оқыңыз, сосын тапсырмаларды орындап, өзіңізді тексеріңіз.')
add('n.tab.texts', 'n', 'Тексты. Читай, слушай и отвечай на вопросы к тексту.',
    'Мәтіндер. Мәтінді оқыңыз, тыңдаңыз да, сұрақтарға жауап беріңіз.')
add('n.tab.test', 'n', 'Итоговый тест по теме. Тема засчитается, если ты наберёшь не меньше семидесяти процентов.',
    'Тақырып бойынша қорытынды тест. Кемінде жетпіс пайыз жинасаңыз, тақырып есептеледі.')
add('n.next.words', 'n', 'Давай ещё раз повторим слова, которые пока не отмечены как знакомые.', 'Әзірге таныс деп белгіленбеген сөздерді тағы қайталайық.')
add('n.next.grammar', 'n', 'Слова готовы. Переходи к грамматике.', 'Сөздер дайын. Грамматикаға көшіңіз.')
add('n.next.texts', 'n', 'С грамматикой справились. Теперь тексты.', 'Грамматикамен жұмыс біткен. Енді мәтіндерге өтіңіз.')
add('n.next.test', 'n', 'Всё пройдено. Пора на тест по теме.', 'Бәрі өтілді. Тақырып тестіне кірісетін уақыт.')
add('n.next.topic', 'n', 'Тема засчитана. Переходи к следующей.', 'Тақырып есептелді. Келесісіне өтіңіз.')
add('n.next.level', 'n', 'Все темы уровня пройдены. Можно переходить к следующему уровню.', 'Деңгейдің барлық тақырыбы өтілді. Келесі деңгейге өтуге болады.')
# тренер
add('c.back', 'c', 'С возвращением! Продолжим с того места, где остановились.', 'Қош келдіңіз! Тоқтаған жерімізден жалғастырамыз.')
for k, (ru_h, ru_m, ru_l, kk_h, kk_m, kk_l) in {
    'quiz': ('Отлично! Почти без ошибок.', 'Хороший результат. Посмотри ошибки, они подскажут, что повторить.', 'Ничего страшного. Вернись к карточкам и попробуй ещё раз.',
             'Тамаша! Қатесіз дерлік.', 'Жақсы нәтиже. Қателерді қараңыз, не қайталау керегін көрсетеді.', 'Қорықпаңыз. Карталарға оралып, қайтадан көріңіз.'),
    'gram': ('Грамматика даётся тебе хорошо.', 'Неплохо. Загляни в разбор и перечитай правило.', 'Давай ещё раз прочитаем правило и попробуем снова.',
             'Грамматика жақсы шығып жатыр.', 'Жаман емес. Талдауға қарап, ережені қайта оқыңыз.', 'Ережені тағы бір рет оқып, қайта көрейік.'),
}.items():
    add(f'c.{k}.high', 'c', ru_h, kk_h); add(f'c.{k}.mid', 'c', ru_m, kk_m); add(f'c.{k}.low', 'c', ru_l, kk_l)
add('c.test.pass', 'c', 'Тема засчитана. Так держать!', 'Тақырып есептелді. Осылай жалғастырыңыз!')
add('c.test.fail', 'c', 'Совсем чуть-чуть не хватило до семидесяти процентов. Повтори слова и попробуй снова.', 'Жетпіс пайызға аздап жетпеді. Сөздерді қайталап, қайта көріңіз.')
tips = [('Совет: повторяй слова вслух. Так они запоминаются легче.', 'Кеңес: сөздерді дауыстап қайталаңыз. Сонда олар жақсы есте қалады.'),
        ('Совет: занимайся понемногу, но каждый день. Это лучше, чем много и редко.', 'Кеңес: аз-аздан, бірақ күнде жаттығыңыз. Бұл сирек әрі көп жаттығудан жақсы.'),
        ('Совет: после текста перескажи его своими словами.', 'Кеңес: мәтіннен кейін оны өз сөзіңізбен айтып беріңіз.'),
        ('Совет: слово лучше учить в предложении, а не по отдельности.', 'Кеңес: сөзді жеке емес, сөйлемнің ішінде үйренген жақсы.'),
        ('Совет: ошибки в тесте подсказывают, что повторить.', 'Кеңес: тесттегі қателер нені қайталау керегін көрсетеді.'),
        ('Совет: если устал, сделай перерыв на пять минут и вернись.', 'Кеңес: шаршасаңыз, бес минут үзіліс жасап, қайта оралыңыз.')]
for i, (r, k) in enumerate(tips, 1): add(f'c.tip.{i}', 'c', r, k)
(ROOT / 'tools' / 'guide' / 'script.json').write_text(json.dumps(S, ensure_ascii=False, indent=1), encoding='utf-8')
chars = sum(len(x['ru']) + len(x['kk']) for x in S)
(ROOT / 'tools' / 'kk-review-guide-2026-11-21.md').write_text('# Казахские реплики голосового гида (ждут носителя)\n\nРоль n - Даулет (проводник), c - Айгүль (тренер). После правки: `python3 tools/guide/make_script.py` и `python3 tools/guide/guide_tts.py`.\n\n' +
    '\n'.join(f"- `{x['key']}` ({x['role']}): {x['kk']}" for x in S) + '\n', encoding='utf-8')
print(len(S), 'реплик,', chars, 'знаков на оба языка')
